<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Mini Spreadsheet</title>
<style>
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-width: 600px;
    min-height: 400px;
    font-family: Arial, sans-serif;
    background: #f3f5f7;
    color: #202124;
  }
  .app {
    min-width: 600px;
    min-height: 400px;
    padding: 18px;
  }
  h1 {
    margin: 0 0 14px;
    font-size: 22px;
  }
  .toolbar {
    display: flex;
    gap: 10px;
    align-items: center;
    margin-bottom: 12px;
  }
  button {
    padding: 7px 13px;
    border: 1px solid #999;
    border-radius: 4px;
    background: white;
    cursor: pointer;
  }
  button:hover { background: #eaf2ff; }
  .sheet {
    display: grid;
    grid-template-columns: 42px repeat(10, minmax(52px, 1fr));
    grid-template-rows: 28px repeat(10, 32px);
    min-width: 600px;
    min-height: 380px;
    overflow: auto;
    border: 1px solid #999;
    background: white;
  }
  .corner, .col-header, .row-header {
    display: flex;
    align-items: center;
    justify-content: center;
    background: #e1e5e9;
    border-right: 1px solid #aaa;
    border-bottom: 1px solid #aaa;
    font-weight: bold;
    font-size: 13px;
  }
  .cell {
    width: 100%;
    min-width: 0;
    border: 0;
    border-right: 1px solid #ccc;
    border-bottom: 1px solid #ccc;
    padding: 5px 7px;
    outline: none;
    background: #fff;
    font: inherit;
    font-size: 13px;
  }
  .cell:focus {
    background: #fffde7;
    box-shadow: inset 0 0 0 2px #4a90e2;
  }
  #csv {
    display: block;
    width: 100%;
    min-height: 90px;
    margin-top: 12px;
    padding: 8px;
    resize: vertical;
    border: 1px solid #aaa;
    font: 12px monospace;
  }
</style>
</head>
<body>
<div class="app">
  <h1>Mini Spreadsheet</h1>
  <div class="toolbar">
    <button id="export" type="button">Export CSV</button>
  </div>
  <div class="sheet" id="sheet">
    <div class="corner"></div>
  </div>
  <textarea id="csv" aria-label="CSV export"></textarea>
</div>

<script>
(function () {
  const cols = "ABCDEFGHIJ".split("");
  const rows = Array.from({ length: 10 }, (_, i) => i + 1);
  const data = {};
  const elements = {};

  for (const col of cols) {
    const header = document.createElement("div");
    header.className = "col-header";
    header.textContent = col;
    document.getElementById("sheet").appendChild(header);
  }

  for (const row of rows) {
    const rowHeader = document.createElement("div");
    rowHeader.className = "row-header";
    rowHeader.textContent = row;
    document.getElementById("sheet").appendChild(rowHeader);

    for (const col of cols) {
      const name = col + row;
      data[name] = "";
      const input = document.createElement("input");
      input.className = "cell";
      input.id = "cell-" + name;
      input.type = "text";
      input.autocomplete = "off";
      input.spellcheck = false;
      input.value = "";
      input.dataset.editing = "false";

      input.addEventListener("focus", function () {
        input.dataset.editing = "true";
        input.value = data[name];
        input.select();
      });

      input.addEventListener("blur", function () {
        if (input.dataset.editing === "true") commit(name);
      });

      input.addEventListener("keydown", function (event) {
        if (event.key === "Enter") {
          event.preventDefault();
          commit(name);
          input.blur();
        }
      });

      elements[name] = input;
      document.getElementById("sheet").appendChild(input);
    }
  }

  function tokenize(source) {
    const tokens = [];
    let i = 0;
    while (i < source.length) {
      if (/\s/.test(source[i])) {
        i++;
        continue;
      }
      const rest = source.slice(i);
      const number = rest.match(/^(?:\d+(?:\.\d*)?|\.\d+)/);
      if (number) {
        tokens.push({ type: "number", value: Number(number[0]) });
        i += number[0].length;
        continue;
      }
      const ref = rest.match(/^[A-Za-z]+[0-9]+/);
      if (ref) {
        tokens.push({ type: "ref", value: ref[0].toUpperCase() });
        i += ref[0].length;
        continue;
      }
      if ("+-*/()".includes(source[i])) {
        tokens.push({ type: source[i], value: source[i] });
        i++;
        continue;
      }
      throw new Error("bad token");
    }
    tokens.push({ type: "eof" });
    return tokens;
  }

  function parseFormula(source, resolve) {
    const tokens = tokenize(source);
    let pos = 0;

    function accept(type) {
      if (tokens[pos].type === type) return tokens[pos++];
      return null;
    }

    function primary() {
      if (accept("(")) {
        const value = expression();
        if (!accept(")")) throw new Error("missing paren");
        return value;
      }
      if (tokens[pos].type === "number") return tokens[pos++].value;
      if (tokens[pos].type === "ref") {
        const ref = tokens[pos++].value;
        if (!/^([A-J])(10|[1-9])$/.test(ref)) throw new Error("bad ref");
        return resolve(ref);
      }
      throw new Error("expected value");
    }

    function unary() {
      if (accept("+")) return unary();
      if (accept("-")) return -unary();
      return primary();
    }

    function term() {
      let value = unary();
      while (tokens[pos].type === "*" || tokens[pos].type === "/") {
        const op = tokens[pos++].type;
        const right = unary();
        if (op === "*") value *= right;
        else {
          if (right === 0) throw new Error("division");
          value /= right;
        }
      }
      return value;
    }

    function expression() {
      let value = term();
      while (tokens[pos].type === "+" || tokens[pos].type === "-") {
        const op = tokens[pos++].type;
        const right = term();
        value = op === "+" ? value + right : value - right;
      }
      return value;
    }

    const result = expression();
    if (tokens[pos].type !== "eof" || !Number.isFinite(result)) {
      throw new Error("invalid formula");
    }
    return String(result);
  }

  function recalculate() {
    const state = {};
    const values = {};
    const stack = [];
    const cycle = new Set();

    function evaluate(name) {
      if (state[name] === "done") return values[name];
      if (state[name] === "visiting") {
        const index = stack.indexOf(name);
        for (let i = index; i < stack.length; i++) cycle.add(stack[i]);
        cycle.add(name);
        throw new Error("cycle");
      }

      state[name] = "visiting";
      stack.push(name);
      const raw = data[name];

      try {
        if (raw === "") {
          values[name] = "0";
        } else if (raw.charAt(0) !== "=") {
          values[name] = raw;
        } else {
          values[name] = parseFormula(raw.slice(1), function (ref) {
            const value = evaluate(ref);
            const number = Number(value);
            if (!Number.isFinite(number)) throw new Error("non-number");
            return number;
          });
        }
        state[name] = "done";
        return values[name];
      } catch (error) {
        values[name] = cycle.has(name) ? "#CYCLE" : "#ERR";
        state[name] = "done";
        throw error;
      } finally {
        stack.pop();
      }
    }

    for (const name of Object.keys(data)) {
      try { evaluate(name); } catch (_) {}
    }

    for (const name of Object.keys(data)) {
      elements[name].value = values[name] ?? "#ERR";
      if (elements[name].dataset.editing !== "true") {
        elements[name].value = values[name] ?? "#ERR";
      }
    }
    return values;
  }

  function commit(name) {
    data[name] = elements[name].value;
    elements[name].dataset.editing = "false";
    recalculate();
  }

  document.getElementById("export").addEventListener("click", function () {
    const values = recalculate();
    const lines = rows.map(row =>
      cols.map(col => values[col + row] ?? "").join(",")
    );
    document.getElementById("csv").value = lines.join("\n");
  });

  window.sheet = {
    set: function (name, value) {
      name = String(name).toUpperCase();
      if (!data.hasOwnProperty(name)) return;
      data[name] = String(value);
      elements[name].dataset.editing = "false";
      recalculate();
    },
    get: function (name) {
      name = String(name).toUpperCase();
      const values = recalculate();
      return values[name];
    },
    raw: function (name) {
      name = String(name).toUpperCase();
      return data[name];
    }
  };

  recalculate();
})();
</script>
</body>
</html>
